#!/usr/bin/env python3
"""End-to-end tests for update.sh + wizard.py fetch-versions/generate.

Runs update.sh in a throwaway copy of the package (no git, like a release
tgz), against a local mock of the versions API and a fake `docker` binary
that only records its arguments. No network access and no Docker needed.

Usage: python3 .github/scripts/test_update.py
"""

import hashlib
import http.server
import os
import re
import shutil
import subprocess
import sys
import tempfile
import threading
import time
from pathlib import Path

REPO = Path(__file__).resolve().parents[2]
FIXTURE = REPO / ".github" / "ci" / "versions-ci.env"
PACKAGE_FILES = ["wizard.py", "update.sh", "compose-template.yaml", ".env.runtime.example"]
API_TIMEOUT = 2


def read_fixture():
    images = {}
    for line in FIXTURE.read_text().splitlines():
        if line and not line.startswith("#"):
            key, value = line.split("=", 1)
            images[key] = value
    return images


def template_keys():
    keys, service = set(), None
    for line in (REPO / "compose-template.yaml").read_text().splitlines():
        match = re.match(r"^  ([a-zA-Z0-9_.-]+):\s*$", line)
        if match:
            service = match.group(1)
        elif service and line.strip().startswith("image:"):
            if "__CONTAINER_IMAGE_PLACEHOLDER__" in line:
                keys.add(service.upper().replace("-", "_").replace(".", "_") + "_IMAGE")
            service = None
    return keys


FIXTURE_IMAGES = read_fixture()
SAMPLE_KEY = sorted(FIXTURE_IMAGES)[0]


def versions_body(tag, drop=(), missing=(), extra=None, chart="ionos_sbx/marketplace/access-node"):
    lines = [
        "# Generated by access-node-compose-api from dome-gitops",
        f"# chart: {chart}",
        "# gitops-commit: 0000000000000000000000000000000000000000",
        "# generated-at: 2026-01-01T00:00:00Z",
    ]
    if missing:
        lines.append(f"# missing: {','.join(missing)}")
    images = {k: re.sub(r":[^:/]+$", f":{tag}", v) for k, v in FIXTURE_IMAGES.items() if k not in drop}
    images.update(extra or {})
    lines += [f"{k}={images[k]}" for k in sorted(images)]
    return ("\n".join(lines) + "\n").encode()


class MockApi(http.server.BaseHTTPRequestHandler):
    """Path layout: /<scenario>/v1/versions."""

    requests = []

    def log_message(self, *args):
        pass

    def send_body(self, status, body, content_type="text/plain; charset=utf-8", etag=None):
        self.send_response(status)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(body)))
        if etag:
            self.send_header("ETag", etag)
        self.end_headers()
        self.wfile.write(body)

    def serve_versions(self, body):
        etag = '"' + hashlib.sha256(body).hexdigest() + '"'
        if self.headers.get("If-None-Match") == etag:
            self.send_response(304)
            self.send_header("ETag", etag)
            self.end_headers()
            return
        self.send_body(200, body, etag=etag)

    def do_GET(self):
        MockApi.requests.append((self.path, self.headers.get("If-None-Match")))
        scenario = self.path.strip("/").split("/")[0]
        if not self.path.endswith("/v1/versions"):
            self.send_body(404, b"not found")
        elif scenario.startswith("tag-"):
            self.serve_versions(versions_body(scenario[len("tag-"):]))
        elif scenario == "unavailable":
            self.send_body(503, b"not ready")
        elif scenario == "slow":
            time.sleep(API_TIMEOUT + 2)
            self.serve_versions(versions_body("slow"))
        elif scenario == "malformed":
            self.send_body(200, b"this is not a versions list\n")
        elif scenario == "empty":
            self.send_body(200, b"# only comments\n")
        elif scenario == "html":
            self.send_body(200, b"<html><body>Login</body></html>\n", content_type="text/html")
        elif scenario == "bad-image":
            self.send_body(200, versions_body("v9", extra={SAMPLE_KEY: "evil/image:${HOME}"}))
        elif scenario == "huge":
            self.send_body(200, b"# padding\n" * 20000)
        elif scenario == "undeclared-missing":
            self.serve_versions(versions_body("v3", drop=[SAMPLE_KEY]))
        elif scenario == "declared-missing":
            self.serve_versions(versions_body("v3", drop=[SAMPLE_KEY], missing=[SAMPLE_KEY]))
        elif scenario == "unknown-key":
            self.serve_versions(versions_body("v4", extra={"SOMETHING_NEW_IMAGE": "example/new:1.0"}))
        elif scenario == "other-chart":
            self.serve_versions(versions_body("v5", chart="ionos_prod/marketplace/access-node"))
        elif scenario == "one-service":
            self.serve_versions(versions_body("v6", extra={SAMPLE_KEY: re.sub(r":[^:/]+$", ":v8", FIXTURE_IMAGES[SAMPLE_KEY])}))
        elif scenario == "redirect":
            self.send_response(301)
            self.send_header("Location", f"http://127.0.0.1:{self.server.server_port}/tag-v6/v1/versions")
            self.end_headers()
        elif scenario == "redirect-remote":
            self.send_response(302)
            self.send_header("Location", "http://example.com/v1/versions")
            self.end_headers()
        else:
            self.send_body(404, b"unknown scenario")


class QuietServer(http.server.ThreadingHTTPServer):
    daemon_threads = True

    def handle_error(self, request, client_address):
        # The client hanging up early (timeout, oversized answer) is expected here.
        if not isinstance(sys.exc_info()[1], (BrokenPipeError, ConnectionResetError)):
            super().handle_error(request, client_address)


FAKE_DOCKER = """#!/usr/bin/env python3
# Records its arguments; emulates `compose -f FILE config --format json` well
# enough for update.sh (service names and images of a generated compose file).
import json, os, re, sys

args = sys.argv[1:]
with open(os.environ["FAKE_DOCKER_LOG"], "a") as log:
    log.write(" ".join(args) + "\\n")

if "config" in args and "json" in args:
    services, current = {}, None
    for line in open(args[args.index("-f") + 1]):
        match = re.match(r"^  ([a-zA-Z0-9_.-]+):\\s*$", line)
        if match:
            current = match.group(1)
        elif current and line.strip().startswith("image:"):
            services[current] = {"image": line.split(":", 1)[1].strip()}
            current = None
    print(json.dumps({"services": services}))
elif "pull" in args and os.environ.get("FAKE_DOCKER_PULL_FAIL") == "1":
    sys.exit(1)
"""


class Sandbox:
    def __init__(self, port):
        self.port = port
        self.dir = Path(tempfile.mkdtemp(prefix="access-node-test-"))
        for name in PACKAGE_FILES:
            shutil.copy2(REPO / name, self.dir / name)
        bin_dir = self.dir / ".fakebin"
        bin_dir.mkdir()
        (bin_dir / "docker").write_text(FAKE_DOCKER)
        (bin_dir / "docker").chmod(0o755)
        self.docker_log = self.dir / ".docker.log"

    def configure(self, url, environment="sbx"):
        (self.dir / ".env.runtime").write_text(
            f"DOME_ENVIRONMENT={environment}\nVERSIONS_API_URL={url}\nVERSIONS_API_TIMEOUT={API_TIMEOUT}\n"
        )

    def scenario(self, name):
        self.configure(f"http://127.0.0.1:{self.port}/{name}/v1")

    def run(self, dry_run=False, pull_fail=False):
        self.docker_log.write_text("")
        env = dict(os.environ)
        env["PATH"] = f"{self.dir / '.fakebin'}:{env['PATH']}"
        env["FAKE_DOCKER_LOG"] = str(self.docker_log)
        env["DRY_RUN"] = "1" if dry_run else "0"
        env["FAKE_DOCKER_PULL_FAIL"] = "1" if pull_fail else "0"
        result = subprocess.run(
            [str(self.dir / "update.sh")], cwd=self.dir, env=env, capture_output=True, text=True, timeout=60
        )
        return result.returncode, result.stdout + result.stderr

    def read(self, name):
        path = self.dir / name
        return path.read_text() if path.exists() else None

    @property
    def docker_calls(self):
        return [line for line in self.docker_log.read_text().splitlines() if line]

    def cleanup(self):
        shutil.rmtree(self.dir, ignore_errors=True)


failures = []


def check(condition, message, output=""):
    if condition:
        print(f"  ok    {message}")
    else:
        print(f"  FAIL  {message}")
        if output:
            print("        " + output.strip().replace("\n", "\n        "))
        failures.append(message)


def assert_untouched(box, before_versions, before_compose, code, output, expected_code=2):
    check(code == expected_code, f"exit code {expected_code} (got {code})", output)
    check(box.read("versions-sbx.env") == before_versions, "versions-sbx.env unchanged")
    check(box.read("compose.yaml") == before_compose, "compose.yaml unchanged")
    check(box.docker_calls == [], "docker not called")
    check(box.read("compose.yaml.new") is None, "no compose.yaml.new left behind")


def main():
    print("== fixture vs template")
    check(set(FIXTURE_IMAGES) == template_keys(),
          ".github/ci/versions-ci.env keys match the template placeholders",
          f"only in fixture: {sorted(set(FIXTURE_IMAGES) - template_keys())}; "
          f"only in template: {sorted(template_keys() - set(FIXTURE_IMAGES))}")

    server = QuietServer(("127.0.0.1", 0), MockApi)
    threading.Thread(target=server.serve_forever, daemon=True).start()
    port = server.server_port

    box = Sandbox(port)
    first = Sandbox(port)
    try:
        print("== configuration errors (fresh install)")
        first.configure("")
        code, out = first.run(dry_run=True)
        check(code == 1 and "VERSIONS_API_URL is not set" in out, "missing VERSIONS_API_URL is an error", out)
        first.configure("http://example.com/v1")
        code, out = first.run(dry_run=True)
        check(code == 1 and "https://" in out, "plain http to a remote host is rejected", out)

        print("== first install with the API down")
        first.scenario("unavailable")
        code, out = first.run(dry_run=True)
        check(code == 1, f"exit code 1 (got {code})", out)
        check(first.read("versions-sbx.env") is None and first.read("compose.yaml") is None, "nothing generated")

        print("== first install with a service reported missing")
        first.scenario("declared-missing")
        code, out = first.run(dry_run=True)
        check(code == 1 and "no previous version" in out, "missing key without a previous version is an error", out)

        print("== first install (wizard step 3, dry run)")
        box.scenario("tag-v1")
        code, out = box.run(dry_run=True)
        check(code == 0, f"exit code 0 (got {code})", out)
        versions = box.read("versions-sbx.env") or ""
        compose = box.read("compose.yaml") or ""
        check("# etag: " in versions, "ETag stored in versions-sbx.env")
        check(all(f"{k}=" in versions for k in FIXTURE_IMAGES), "all keys saved")
        check("__CONTAINER_IMAGE_PLACEHOLDER__" not in compose and ":v1" in compose, "compose.yaml fully rendered")
        check(box.docker_calls == [], "dry run: docker not called")

        print("== unchanged list -> 304, no restart")
        MockApi.requests.clear()
        code, out = box.run()
        check(code == 0, f"exit code 0 (got {code})", out)
        check(MockApi.requests and MockApi.requests[-1][1], "If-None-Match sent")
        check("304" in out, "server answered 304", out)
        check(box.docker_calls == [], "docker not called")

        print("== new versions -> pull + up")
        box.scenario("tag-v2")
        code, out = box.run()
        check(code == 0, f"exit code 0 (got {code})", out)
        check(":v2" in (box.read("compose.yaml") or ""), "compose.yaml updated to v2")
        calls = box.docker_calls
        check(any(" pull" in c for c in calls) and any(" up -d" in c for c in calls), "docker pull and up called", "\n".join(calls))
        pull_index = next((i for i, c in enumerate(calls) if " pull" in c), -1)
        check(pull_index >= 0 and "compose.yaml.new" in calls[pull_index], "pull runs on the candidate file", "\n".join(calls))

        good_versions, good_compose = box.read("versions-sbx.env"), box.read("compose.yaml")
        for name in ("unavailable", "malformed", "empty", "html", "bad-image", "huge", "undeclared-missing", "redirect-remote"):
            print(f"== API answer rejected: {name}")
            box.scenario(name)
            code, out = box.run()
            assert_untouched(box, good_versions, good_compose, code, out)

        print("== API timeout")
        box.scenario("slow")
        started = time.time()
        code, out = box.run()
        assert_untouched(box, good_versions, good_compose, code, out)
        check(time.time() - started < API_TIMEOUT + 10, "gave up within the timeout")

        print("== wrong path on the API host (404)")
        box.configure(f"http://127.0.0.1:{port}/nowhere")
        code, out = box.run()
        assert_untouched(box, good_versions, good_compose, code, out)

        print("== missing VERSIONS_API_URL on an existing install")
        box.configure("")
        code, out = box.run()
        assert_untouched(box, good_versions, good_compose, code, out, expected_code=1)

        print("== pull failure keeps the running compose.yaml")
        box.scenario("tag-v7")
        code, out = box.run(pull_fail=True)
        check(code != 0, f"non-zero exit code (got {code})", out)
        check(box.read("compose.yaml") == good_compose, "compose.yaml unchanged")
        check(not any(" up " in c or c.endswith(" up") or " up -d" in c for c in box.docker_calls), "docker up not called")
        print("== next run retries the pull (304 but compose.yaml still outdated)")
        code, out = box.run()
        check(code == 0 and ":v7" in (box.read("compose.yaml") or ""), "compose.yaml updated to v7 on retry", out)

        print("== service reported missing keeps its previous version")
        box.scenario("declared-missing")
        code, out = box.run()
        check(code == 0, f"exit code 0 (got {code})", out)
        versions = box.read("versions-sbx.env") or ""
        check(f"{SAMPLE_KEY}=" in versions and re.search(rf"^{SAMPLE_KEY}=.*:v7$", versions, re.M), f"{SAMPLE_KEY} kept at v7", versions)
        check(f"# kept-previous: {SAMPLE_KEY}" in versions, "kept key recorded in the file")
        check("missing" in out and "keeping the previous version" in out, "warning printed", out)
        check(":v3" in (box.read("compose.yaml") or ""), "the other services moved to v3")

        print("== unknown key in the answer is ignored")
        box.scenario("unknown-key")
        code, out = box.run()
        check(code == 0 and "SOMETHING_NEW_IMAGE" in out, "accepted with a warning", out)
        check("SOMETHING_NEW_IMAGE" not in (box.read("versions-sbx.env") or ""), "unknown key not saved")

        print("== chart of another environment -> warning only")
        box.scenario("other-chart")
        code, out = box.run()
        check(code == 0 and "doesn't look like" in out, "warning about the chart", out)

        print("== redirect to an allowed URL is followed")
        box.scenario("redirect")
        code, out = box.run()
        check(code == 0 and ":v6" in (box.read("compose.yaml") or ""), "compose.yaml updated to v6", out)

        print("== only the service whose image changed is pulled")
        box.scenario("one-service")
        code, out = box.run()
        pulls = [c for c in box.docker_calls if " pull" in c]
        sample_service = SAMPLE_KEY[: -len("_IMAGE")].lower().replace("_", "-")
        check(code == 0 and ":v8" in (box.read("compose.yaml") or ""), "compose.yaml updated", out)
        check(len(pulls) == 1 and pulls[0].endswith(f" pull {sample_service}"), f"pull limited to {sample_service}", "\n".join(pulls))

        print("== compose.yaml change without image changes: no pull, still applied")
        template = box.dir / "compose-template.yaml"
        template.write_text(template.read_text().replace("networks:\n  access-node:\n", "networks:\n  access-node:\n    # changed\n", 1))
        code, out = box.run()
        calls = box.docker_calls
        check(code == 0 and "# changed" in (box.read("compose.yaml") or ""), "compose.yaml updated", out)
        check(not any(" pull" in c for c in calls) and any(" up -d" in c for c in calls), "no pull, up called", "\n".join(calls))

        print("== a concurrent run is skipped")
        if shutil.which("flock"):
            lock = subprocess.Popen(["flock", str(box.dir / ".update.lock"), "sleep", "5"])
            time.sleep(0.5)
            code, out = box.run()
            lock.wait()
            check(code == 0 and "already running" in out, "second run skipped", out)
        else:
            print("  skip  flock not available")
    finally:
        server.shutdown()
        box.cleanup()
        first.cleanup()

    print()
    if failures:
        print(f"{len(failures)} check(s) failed.")
        sys.exit(1)
    print("All checks passed.")


if __name__ == "__main__":
    main()
